public class Solution {
    public int NumFactoredBinaryTrees(int[] arr) {
        Array.Sort(arr);
        int mod = 1_000_000_007;
        var dp = new Dictionary<int, long>(arr.Length);

        long totalTrees = 0;

        for (int i = 0; i < arr.Length; i++) {
            long count = 1;
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int right = arr[i] / arr[j];
                    if (dp.TryGetValue(right, out long rightCount)) {
                        count = (count + dp[arr[j]] * rightCount) % mod;
                    }
                }
            }
            dp[arr[i]] = count;
            totalTrees = (totalTrees + count) % mod;
        }

        return (int)totalTrees;
    }
}
