using System;
using System.Numerics;

public class Solution {
    public int MaxScore(int[] nums) {
        int m = nums.Length;
        int n = m / 2;
        int totalMasks = 1 << m;

        int[,] gcd = new int[m, m];
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                gcd[i, j] = GCD(nums[i], nums[j]);
            }
        }

        int[] dp = new int[totalMasks];

        for (int mask = 0; mask < totalMasks; mask++) {
            int cnt = BitOperations.PopCount((uint)mask);
            if ((cnt & 1) != 0) continue;

            int step = cnt / 2 + 1;
            if (step > n) continue;

            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) continue;
                for (int j = i + 1; j < m; j++) {
                    if ((mask & (1 << j)) != 0) continue;

                    int nextMask = mask | (1 << i) | (1 << j);
                    int score = dp[mask] + step * gcd[i, j];
                    if (score > dp[nextMask]) {
                        dp[nextMask] = score;
                    }
                }
            }
        }

        return dp[totalMasks - 1];
    }

    private int GCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
