    }

    private void Dfs(TreeNode node, TreeNode parent, int depth, int x, int y) {
        if (node == null) return;

        if (node.val == x) {
            depthX = depth;
            parentX = parent;
        } else if (node.val == y) {
            depthY = depth;
            parentY = parent;
        }

        if (parentX != null && parentY != null) return;

        Dfs(node.left, node, depth + 1, x, y);
        Dfs(node.right, node, depth + 1, x, y);
    }
