        int n = grid[0].Length;

        int[][] rowSum = new int[m][];
        for (int i = 0; i < m; i++) {
            rowSum[i] = new int[n + 1];
            for (int j = 0; j < n; j++) {
                rowSum[i][j + 1] = rowSum[i][j] + grid[i][j];
            }
        }

        int[][] colSum = new int[m + 1][];
        for (int i = 0; i <= m; i++) {
            colSum[i] = new int[n];
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                colSum[i + 1][j] = colSum[i][j] + grid[i][j];
            }
        }

        for (int k = Math.Min(m, n); k >= 2; k--) {
            for (int r = 0; r <= m - k; r++) {
                for (int c = 0; c <= n - k; c++) {
                    int diag1 = 0;
                    int diag2 = 0;
                    for (int d = 0; d < k; d++) {
                        diag1 += grid[r + d][c + d];
                        diag2 += grid[r + d][c + k - 1 - d];
                    }

                    if (diag1 != diag2) continue;

                    int target = diag1;
                    bool valid = true;

                    for (int i = 0; i < k; i++) {
                        if (rowSum[r + i][c + k] - rowSum[r + i][c] != target) {
                            valid = false;
                            break;
                        }
                    }

                    if (!valid) continue;

                    for (int j = 0; j < k; j++) {
                        if (colSum[r + k][c + j] - colSum[r][c + j] != target) {
                            valid = false;
                            break;
                        }
                    }

                    if (valid) {
                        return k;
                    }
                }
            }
        }

        return 1;
    }
