using System;

public class Solution {
    public long MaximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.Length;
        for (int i = 0; i < n; i++) {
            if (flowers[i] > target) {
                flowers[i] = target;
            }
        }
        Array.Sort(flowers);

        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + flowers[i];
        }

        long maxBeauty = 0;

        for (int c = 0; c <= n; c++) {
            long costSuffix = (long)c * target - (pref[n] - pref[n - c]);
            if (costSuffix > newFlowers) {
                break;
            }

            long rem = newFlowers - costSuffix;
            int len = n - c;

            if (len == 0) {
                long beauty = (long)n * full;
                if (beauty > maxBeauty) {
                    maxBeauty = beauty;
                }
                continue;
            }

            long low = flowers[0];
            long high = target - 1;
            long bestMin = flowers[0];

            while (low <= high) {
                long mid = low + (high - low) / 2;

                int l = 0, r = len;
                while (l < r) {
                    int m = (l + r) / 2;
                    if (flowers[m] < mid) {
                        l = m + 1;
                    } else {
                        r = m;
                    }
                }

                long cost = (long)l * mid - pref[l];
                if (cost <= rem) {
                    bestMin = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            long currentBeauty = (long)c * full + bestMin * partial;
            if (currentBeauty > maxBeauty) {
                maxBeauty = currentBeauty;
            }
        }

        return maxBeauty;
    }
}
