public class Solution {
    public int MinDays(int[][] grid) {
        if (CountIslands(grid) != 1) {
            return 0;
        }

        int m = grid.Length;
        int n = grid[0].Length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    if (CountIslands(grid) != 1) {
                        return 1;
                    }
                    grid[i][j] = 1;
                }
            }
        }

        return 2;
    }

    private int CountIslands(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;
        bool[,] visited = new bool[m, n];
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !visited[i, j]) {
                    count++;
                    if (count > 1) return count;
                    Dfs(grid, visited, i, j, m, n);
                }
            }
        }

        return count;
    }

    private void Dfs(int[][] grid, bool[,] visited, int r, int c, int m, int n) {
        visited[r, c] = true;
        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1 && !visited[nr, nc]) {
                Dfs(grid, visited, nr, nc, m, n);
            }
        }
    }
}
