using System;

public class Solution {
    public int MinSessions(int[] tasks, int sessionTime) {
        int n = tasks.Length;
        int numStates = 1 << n;
        int[] sessions = new int[numStates];
        int[] lastSession = new int[numStates];

        Array.Fill(sessions, int.MaxValue);

        sessions[0] = 1;
        lastSession[0] = 0;

        for (int mask = 0; mask < numStates; mask++) {
            if (sessions[mask] == int.MaxValue) continue;

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    int nextMask = mask | (1 << i);
                    int newSessions = sessions[mask];
                    int newLast = lastSession[mask] + tasks[i];

                    if (newLast > sessionTime) {
                        newSessions++;
                        newLast = tasks[i];
                    }

                    if (newSessions < sessions[nextMask] || 
                       (newSessions == sessions[nextMask] && newLast < lastSession[nextMask])) {
                        sessions[nextMask] = newSessions;
                        lastSession[nextMask] = newLast;
                    }
                }
            }
        }

        return sessions[numStates - 1];
    }
