```csharp
public class Solution {
    private string s1;
    private string s2;
    private sbyte[,,] memo;

    public bool IsScramble(string s1, string s2) {
        this.s1 = s1;
        this.s2 = s2;
        int n = s1.Length;
        memo = new sbyte[n, n, n + 1];
        return Dfs(0, 0, n);
    }

    private bool Dfs(int i, int j, int len) {
        if (memo[i, j, len] != 0) {
            return memo[i, j, len] == 1;
        }

        bool same = true;
        for (int k = 0; k < len; k++) {
            if (s1[i + k] != s2[j + k]) {
                same = false;
                break;
            }
        }
        if (same) {
            memo[i, j, len] = 1;
            return true;
        }

        int[] count = new int[26];
        for (int k = 0; k < len; k++) {
            count[s1[i + k] - 'a']++;
            count[s2[j + k] - 'a']--;
        }
        for (int c = 0; c < 26; c++) {
            if (count[c] != 0) {
                memo[i, j, len] = -1;
                return false;
            }
        }

        for (int k = 1; k < len; k++) {
            if (Dfs(i, j, k) && Dfs(i + k, j + k, len - k)) {
                memo[i, j, len] = 1;
                return true;
            }
            if (Dfs(i, j + len - k, k) && Dfs(i + k, j, len - k)) {
                memo[i, j, len] = 1;
                return true;
            }
        }

        memo[i, j, len] = -1;
        return false;
    }
}
