using System.Collections.Generic;

public class Solution {
    public IList<IList<int>> ShiftGrid(int[][] grid, int k) {
        int m = grid.Length;
        int n = grid[0].Length;
        int total = m * n;
        k %= total;

        IList<IList<int>> result = new List<IList<int>>(m);

        for (int r = 0; r < m; r++) {
            List<int> row = new List<int>(n);
            for (int c = 0; c < n; c++) {
                int origIdx = (r * n + c - k + total) % total;
                int origR = origIdx / n;
                int origC = origIdx % n;
                row.Add(grid[origR][origC]);
            }
            result.Add(row);
        }

        return result;
    }
}
