using System;

public class Solution {
    public bool CanPartitionKSubsets(int[] nums, int k) {
        int totalSum = 0;
        int maxNum = 0;
        foreach (int num in nums) {
            totalSum += num;
            if (num > maxNum) {
                maxNum = num;
            }
        }

        if (totalSum % k != 0) {
            return false;
        }

        int target = totalSum / k;
        if (maxNum > target) {
            return false;
        }

        int n = nums.Length;
        int numSubsets = 1 << n;
        bool[] dp = new bool[numSubsets];
        int[] currentSum = new int[numSubsets];

        dp[0] = true;
        currentSum[0] = 0;

        for (int mask = 0; mask < numSubsets; mask++) {
            if (!dp[mask]) {
                continue;
            }

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    if (currentSum[mask] + nums[i] <= target) {
                        int nextMask = mask | (1 << i);
                        if (!dp[nextMask]) {
                            dp[nextMask] = true;
                            currentSum[nextMask] = (currentSum[mask] + nums[i]) % target;
                        }
                    }
                }
            }
        }

        return dp[numSubsets - 1];
    }
}
