public class Solution {
    public int SplitArray(int[] nums, int k) {
        long low = 0;
        long high = 0;

        foreach (int num in nums) {
            if (num > low) {
                low = num;
            }
            high += num;
        }

        while (low < high) {
            long mid = low + (high - low) / 2;
            int count = 1;
            long currentSum = 0;

            foreach (int num in nums) {
                if (currentSum + num > mid) {
                    count++;
                    currentSum = num;
                } else {
                    currentSum += num;
                }
            }

            if (count <= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return (int)low;
    }
}
