using System;
using System.Collections.Generic;

public class Solution {
    public int MinStickers(string[] stickers, string target) {
        int m = target.Length;
        int maxMask = 1 << m;
        int[] dp = new int[maxMask];
        Array.Fill(dp, -1);
        dp[0] = 0;

        int n = stickers.Length;
        int[][] stickerCounts = new int[n][];
        for (int i = 0; i < n; i++) {
            stickerCounts[i] = new int[26];
            foreach (char c in stickers[i]) {
                stickerCounts[i][c - 'a']++;
            }
        }

        Queue<int> queue = new Queue<int>();
        queue.Enqueue(0);

        while (queue.Count > 0) {
            int mask = queue.Dequeue();
            if (mask == maxMask - 1) {
                return dp[mask];
            }

            int firstUncovered = -1;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) == 0) {
                    firstUncovered = i;
                    break;
                }
            }

            char targetChar = target[firstUncovered];

            for (int i = 0; i < n; i++) {
                if (stickerCounts[i][targetChar - 'a'] == 0) {
                    continue;
                }

                int nextMask = mask;
                int[] remaining = (int[])stickerCounts[i].Clone();

                for (int j = 0; j < m; j++) {
                    if ((nextMask & (1 << j)) == 0) {
                        char c = target[j];
                        if (remaining[c - 'a'] > 0) {
                            remaining[c - 'a']--;
                            nextMask |= (1 << j);
                        }
                    }
                }

                if (dp[nextMask] == -1) {
                    dp[nextMask] = dp[mask] + 1;
                    if (nextMask == maxMask - 1) {
                        return dp[nextMask];
                    }
                    queue.Enqueue(nextMask);
                }
            }
        }

        return -1;
    }
}
