public class Solution {
    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        int size = n * 3;
        int[,] expanded = new int[size, size];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                char ch = grid[r][c];
                if (ch == '/') {
                    expanded[r * 3 + 0, c * 3 + 2] = 1;
                    expanded[r * 3 + 1, c * 3 + 1] = 1;
                    expanded[r * 3 + 2, c * 3 + 0] = 1;
                } else if (ch == '\\') {
                    expanded[r * 3 + 0, c * 3 + 0] = 1;
                    expanded[r * 3 + 1, c * 3 + 1] = 1;
                    expanded[r * 3 + 2, c * 3 + 2] = 1;
                }
            }
        }

        int regions = 0;
        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (expanded[i, j] == 0) {
                    regions++;
                    var queue = new System.Collections.Generic.Queue<(int, int)>();
                    queue.Enqueue((i, j));
                    expanded[i, j] = 1;

                    while (queue.Count > 0) {
                        var (r, c) = queue.Dequeue();
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d];
                            int nc = c + dc[d];
                            if (nr >= 0 && nr < size && nc >= 0 && nc < size && expanded[nr, nc] == 0) {
                                expanded[nr, nc] = 1;
                                queue.Enqueue((nr, nc));
                            }
                        }
                    }
                }
            }
        }

        return regions;
    }
}
