using System.Collections.Generic;

public class Solution {
    public int[] RestoreArray(int[][] adjacentPairs) {
        int n = adjacentPairs.Length + 1;
        var adj = new Dictionary<int, List<int>>(n);

        foreach (var pair in adjacentPairs) {
            int u = pair[0], v = pair[1];
            if (!adj.TryGetValue(u, out var listU)) {
                listU = new List<int>(2);
                adj[u] = listU;
            }
            listU.Add(v);

            if (!adj.TryGetValue(v, out var listV)) {
                listV = new List<int>(2);
                adj[v] = listV;
            }
            listV.Add(u);
        }

        int start = 0;
        foreach (var kvp in adj) {
            if (kvp.Value.Count == 1) {
                start = kvp.Key;
                break;
            }
        }

        int[] result = new int[n];
        result[0] = start;
        result[1] = adj[start][0];

        for (int i = 2; i < n; i++) {
            var neighbors = adj[result[i - 1]];
            result[i] = neighbors[0] == result[i - 2] ? neighbors[1] : neighbors[0];
        }

        return result;
    }
}
