using System;
using System.Collections.Generic;

public class Solution {
    public IList<IList<string>> SuggestedProducts(string[] products, string searchWord) {
        Array.Sort(products, StringComparer.Ordinal);

        var result = new List<IList<string>>();
        int left = 0;
        int right = products.Length - 1;

        for (int i = 0; i < searchWord.Length; i++) {
            char c = searchWord[i];

            while (left <= right && (products[left].Length <= i || products[left][i] != c)) {
                left++;
            }
            while (left <= right && (products[right].Length <= i || products[right][i] != c)) {
                right--;
            }

            var currentSuggestions = new List<string>();
            for (int j = left; j <= Math.Min(left + 2, right); j++) {
                currentSuggestions.Add(products[j]);
            }
            result.Add(currentSuggestions);
        }

        return result;
    }
}
