using System;
using System.Collections.Generic;

public class Solution {
    public int[] GetCoprimes(int[] nums, int[][] edges) {
        int n = nums.Length;

        // Precompute coprime values for each number in [1, 50]
        List<int>[] coprimes = new List<int>[51];
        for (int i = 1; i <= 50; i++) {
            coprimes[i] = new List<int>();
            for (int j = 1; j <= 50; j++) {
                if (Gcd(i, j) == 1) {
                    coprimes[i].Add(j);
                }
            }
        }

        // Build adjacency list
        List<int>[] adj = new List<int>[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new List<int>();
        }
        foreach (var edge in edges) {
            adj[edge[0]].Add(edge[1]);
            adj[edge[1]].Add(edge[0]);
        }

        int[] ans = new int[n];
        int[] parent = new int[n];
        int[] depth = new int[n];
        int[] edgeIdx = new int[n];
        Array.Fill(parent, -1);

        // Stacks for each value 1..50
        List<(int node, int depth)>[] valStacks = new List<(int node, int depth)>[51];
        for (int i = 1; i <= 50; i++) {
            valStacks[i] = new List<(int, int)>();
        }

        // Iterative DFS
        Stack<int> stack = new Stack<int>();

        // Process root (0)
        ans[0] = -1;
        depth[0] = 0;
        valStacks[nums[0]].Add((0, 0));
        stack.Push(0);

        while (stack.Count > 0) {
            int u = stack.Peek();

            if (edgeIdx[u] < adj[u].Count) {
                int v = adj[u][edgeIdx[u]++];
                if (v == parent[u]) {
                    continue;
                }

                parent[v] = u;
                depth[v] = depth[u] + 1;

                int bestDepth = -1;
                int bestNode = -1;
                int val = nums[v];

                foreach (int c in coprimes[val]) {
                    var list = valStacks[c];
                    if (list.Count > 0) {
                        var top = list[list.Count - 1];
                        if (top.depth > bestDepth) {
                            bestDepth = top.depth;
                            bestNode = top.node;
                        }
                    }
                }
                ans[v] = bestNode;

                valStacks[nums[v]].Add((v, depth[v]));
                stack.Push(v);
            } else {
                valStacks[nums[u]].RemoveAt(valStacks[nums[u]].Count - 1);
                stack.Pop();
            }
        }

        return ans;
    }

    private static int Gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
