using System.Text;

public class Solution {
    public string StrWithout3a3b(int a, int b) {
        StringBuilder sb = new StringBuilder();
        while (a > 0 || b > 0) {
            bool writeA = false;
            int len = sb.Length;
            if (len >= 2 && sb[len - 1] == sb[len - 2]) {
                if (sb[len - 1] == 'b') {
                    writeA = true;
                }
            } else {
                if (a >= b) {
                    writeA = true;
                }
            }

            if (writeA) {
                sb.Append('a');
                a--;
            } else {
                sb.Append('b');
                b--;
            }
        }
        return sb.ToString();
    }
}
