public class Solution {
    public bool IsMatch(string s, string p) {
        int sIdx = 0, pIdx = 0;
        int starIdx = -1, sTmpIdx = -1;

        while (sIdx < s.Length) {
            if (pIdx < p.Length && (p[pIdx] == '?' || p[pIdx] == s[sIdx])) {
                sIdx++;
                pIdx++;
            } else if (pIdx < p.Length && p[pIdx] == '*') {
                starIdx = pIdx;
                sTmpIdx = sIdx;
                pIdx++;
            } else if (starIdx != -1) {
                pIdx = starIdx + 1;
                sTmpIdx++;
                sIdx = sTmpIdx;
            } else {
                return false;
            }
        }

        while (pIdx < p.Length && p[pIdx] == '*') {
            pIdx++;
        }

        return pIdx == p.Length;
    }
}
